const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizePhone(value) {
  const phone = normalizeString(value);
  if (!phone) return "";
  return phone.replace(/\s+/g, "");
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-M",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        whatsapp_message: null,
        provider_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-M will not prepare WhatsApp message when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "prepare_whatsapp_message") {
  return fail({
    code: "WHATSAPP_NOT_REQUESTED",
    message: "source.next_action is not prepare_whatsapp_message.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.provider) {
  return fail({
    code: "MISSING_PROVIDER",
    message: "config.provider is required."
  });
}

if (!config.mode) {
  return fail({
    code: "MISSING_MODE",
    message: "config.mode is required."
  });
}

const provider = normalizeString(config.provider).toLowerCase();
const mode = normalizeString(config.mode).toLowerCase();
const messageFormat = normalizeString(config.message_format || "text").toLowerCase();

const supportedProviders = ["whatsapp_cloud_api", "twilio_whatsapp", "wati", "manual"];
const supportedModes = ["provider_handoff", "manual_handoff"];
const supportedFormats = ["text", "template"];

if (!supportedProviders.includes(provider)) {
  return fail({
    code: "UNSUPPORTED_PROVIDER",
    message: "config.provider is not supported in C2-M v1.",
    details: [{ provider, supported_providers: supportedProviders }]
  });
}

if (!supportedModes.includes(mode)) {
  return fail({
    code: "UNSUPPORTED_MODE",
    message: "config.mode is not supported in C2-M v1.",
    details: [{ mode, supported_modes: supportedModes }]
  });
}

if (!supportedFormats.includes(messageFormat)) {
  return fail({
    code: "UNSUPPORTED_MESSAGE_FORMAT",
    message: "config.message_format is not supported in C2-M v1.",
    details: [{ message_format: messageFormat, supported_formats: supportedFormats }]
  });
}

if (provider === "manual" && mode !== "manual_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Manual provider supports manual_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider !== "manual" && mode !== "provider_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Provider integrations support provider_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (config.approval_status_required === true) {
  const approved = source.approved_action?.approved === true;
  if (!approved) {
    return fail({
      code: "MESSAGE_NOT_APPROVED",
      message: "Approved action is required before preparing WhatsApp provider handoff.",
      details: [{ approved_action: source.approved_action || null }]
    });
  }
}

const recipientPhone = normalizePhone(payload.recipient_phone);
const messageBody = normalizeString(payload.message_body);
const recipientName = normalizeString(payload.recipient_name);
const messageType = normalizeString(payload.message_type || "manual_message");

if (!recipientPhone) {
  return fail({
    code: "MISSING_RECIPIENT_PHONE",
    message: "input.payload.recipient_phone is required."
  });
}

if (!messageBody && messageFormat === "text") {
  return fail({
    code: "MISSING_MESSAGE_BODY",
    message: "input.payload.message_body is required for text messages."
  });
}

if (Array.isArray(config.allowed_message_types) && config.allowed_message_types.length > 0) {
  if (!config.allowed_message_types.includes(messageType)) {
    return fail({
      code: "MESSAGE_TYPE_NOT_ALLOWED",
      message: "input.payload.message_type is not allowed by config.allowed_message_types.",
      details: [
        {
          message_type: messageType,
          allowed_message_types: config.allowed_message_types
        }
      ]
    });
  }
}

if (provider === "whatsapp_cloud_api" && mode === "provider_handoff" && !config.from_phone_number_id) {
  return fail({
    code: "MISSING_CLOUD_API_PHONE_NUMBER_ID",
    message: "config.from_phone_number_id is required for WhatsApp Cloud API handoff."
  });
}

if (provider === "twilio_whatsapp" && mode === "provider_handoff" && !config.from_whatsapp_number) {
  return fail({
    code: "MISSING_TWILIO_FROM_NUMBER",
    message: "config.from_whatsapp_number is required for Twilio WhatsApp handoff."
  });
}

if (provider === "wati" && mode === "provider_handoff" && !config.wati_api_endpoint) {
  return fail({
    code: "MISSING_WATI_ENDPOINT",
    message: "config.wati_api_endpoint is required for WATI handoff."
  });
}

const whatsappMessage = {
  provider,
  mode,
  status: "ready",
  message_format: messageFormat,
  message_type: messageType,
  recipient: {
    name: recipientName || null,
    phone: recipientPhone
  },
  body: messageBody,
  context: payload.context || null,
  requires_approval: config.requires_approval === true,
  approval_status_required: config.approval_status_required === true,
  prepared_at: nowIso()
};

let providerHandoff = null;
let manualReviewHandoff = null;
let nextAction = config.default_next_action || "whatsapp_message_ready";

if (mode === "manual_handoff") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C2-M",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "manual_whatsapp_message",
      whatsapp_message: whatsappMessage,
      source_result: source,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "manual_whatsapp_message",
      review_reason: "Manual WhatsApp message handling required.",
      reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: config.priority || "normal",
      allowed_actions: ["send_manually", "edit_message", "reject_message", "request_more_info"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
}

if (mode === "provider_handoff") {
  let providerPayload = {};

  if (provider === "whatsapp_cloud_api") {
    providerPayload = {
      provider,
      method: "POST",
      endpoint_template: "https://graph.facebook.com/vXX.X/{phone_number_id}/messages",
      phone_number_id: config.from_phone_number_id,
      business_account_id: config.business_account_id || null,
      body: {
        messaging_product: "whatsapp",
        to: recipientPhone.replace(/^\+/, ""),
        type: messageFormat,
        text: messageFormat === "text" ? { body: messageBody } : undefined
      }
    };
  }

  if (provider === "twilio_whatsapp") {
    providerPayload = {
      provider,
      method: "POST",
      endpoint_template: "Twilio Messages API",
      from: config.from_whatsapp_number,
      to: recipientPhone.startsWith("whatsapp:") ? recipientPhone : `whatsapp:${recipientPhone}`,
      body: messageBody
    };
  }

  if (provider === "wati") {
    providerPayload = {
      provider,
      method: "POST",
      endpoint: config.wati_api_endpoint,
      phone: recipientPhone,
      body: {
        messageText: messageBody
      }
    };
  }

  providerHandoff = {
    next_component: `${provider}_adapter`,
    input: {
      success: true,
      component_id: "C2-M",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "whatsapp_provider_send_request",
      whatsapp_message: whatsappMessage,
      provider_payload: providerPayload,
      source_result: source,
      error: null,
      next_action: "send_whatsapp_message"
    },
    config: {
      provider,
      adapter_required: true,
      default_next_action: "track_message_status"
    }
  };

  nextAction = config.default_next_action || "send_whatsapp_provider_handoff";
}

return [
  {
    json: {
      success: true,
      component_id: "C2-M",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      whatsapp_message: whatsappMessage,
      provider_handoff: providerHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: source,
      error: null,
      next_action: nextAction
    }
  }
];
